class StdinTests(CliCase):
    def test_all_commands_read_stdin(self):
        for argv, want in [
            (("balance", "-"), "1457.50\n"),
            (("summary", "-", "--by", "month"), "2024-03  1457.50\n"),
            (("list", "-", "--category", "groceries"), "2024-03-02 groceries -42.50 weekly shop\n"),
            (("export", "-"), None),
        ]:
            code, out, err = self.run_cli(*argv, stdin=LEDGER)
            self.assertEqual((code, err), (0, ""), argv)
            if want is not None:
                self.assertEqual(out, want)
            else:
                self.assertTrue(out.startswith("date,category,amount,note\n2024-03-01,salary,2500.00,March pay\n"))

    def test_stdin_error(self):
        code, out, err = self.run_cli("balance", "-", stdin="2024-03-01 a 1\nbad\n")
        self.assertEqual((code, out), (1, ""))
        self.assertIn("line 2", err)

    def test_stdin_bytes(self):
        fake = mock.Mock()
        fake.buffer.read.return_value = "2024-03-01 a 1\n".encode("utf-8")
        with mock.patch.object(sys, "stdin", fake):
            self.assertEqual(self.run_cli("balance", "-")[:2], (0, "1.00\n"))


class ClosedStdinTests(CliCase):
    def test_stdin_none(self):
        for command in ("balance", "summary", "list", "export"):
            with self.subTest(command=command):
                code, out, err = self._run_none(command)
                self.assertEqual((code, out), (2, ""))
                self.assertTrue(err.startswith("pennywise: cannot read standard input: "), err)
                self.assertEqual(len(err.splitlines()), 1)
                self.assertNotIn("Traceback", err)

    def _run_none(self, command):
        with mock.patch.object(sys, "stdin", None):
            return self.run_cli(command, "-")

    def test_stdin_closed_file(self):
        fake = io.StringIO("2024-03-01 a 1\n")
        fake.close()
        with mock.patch.object(sys, "stdin", fake):
            code, out, err = self.run_cli("balance", "-")
        self.assertEqual((code, out), (2, ""))
        self.assertTrue(err.startswith("pennywise: cannot read standard input: "), err)
        self.assertNotIn("Traceback", err)

    def test_subprocess_closed_stdin(self):
        env = dict(os.environ, PYTHONPATH=os.path.dirname(os.path.dirname(os.path.abspath(cli.__file__))))
        code = (
            "import os, sys; os.close(0); from pennywise import cli; "
            "sys.exit(cli.main(['balance', '-']))"
        )
        r = subprocess.run(
            [sys.executable, "-c", code],
            stdin=subprocess.DEVNULL, capture_output=True, text=True, env=env, cwd=self.dir,
        )
        self.assertEqual(r.returncode, 2, r.stderr)
        self.assertEqual(r.stdout, "")
        self.assertTrue(r.stderr.startswith("pennywise: cannot read standard input: "), r.stderr)
        self.assertNotIn("Traceback", r.stderr)


