        cases = (
            (("balance", self.path, "extra"), "usage: pennywise balance [-h] [--json] FILE", "extra"),
            (("export", self.path, "--json"), "usage: pennywise export ", "--json"),
            (("summary", self.path, "a", "b"), "usage: pennywise summary ", "a b"),
            (("list", self.path, "--bogus"), "usage: pennywise list ", "--bogus"),
            (("add", self.path, "2024-03-07", "fun", "-1", "note", "--bogus"), "usage: pennywise add ", "--bogus"),
        )
        for argv, usage, leftover in cases:
            code, out, err = self.run_cli(*argv)
            self.assertEqual((code, out), (2, ""), argv)
            self.assertTrue(err.startswith(usage), (argv, err))
            self.assertIn("pennywise: unrecognized arguments: %s\n" % leftover, err)
            self.assertNotIn("COMMAND", err)

    def test_version(self):
        code, out, err = self.run_cli("--version")
        self.assertEqual((code, out, err), (0, "pennywise 0.1.0\n", ""))


